Action: run_sql({'query': "SELECT \n    e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key,\n    ST_Y(e.geom) as lat, ST_X(e.geom) as lon,\n    STRING_AGG(c.category, ', ') as categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE ST_DWithin(e.geom, ST_MakePoint(-111.925, 40.785)::geometry, 0.035) -- roughly 2.5 miles\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key, e.geom\nORDER BY e.num_of_reviews DESC;"})

