Action: run_sql({'query': "SELECT e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key,\n       STRING_AGG(c.category, ', ') as categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE (e.address LIKE '%84116%' OR ST_DWithin(e.geom, ST_MakePoint(-111.925, 40.785)::geometry, 0.025))\n  AND (\n    c.category LIKE '%Breakfast%' \n    OR c.category LIKE '%Diner%' \n    OR c.category LIKE '%Mexican%' \n    OR c.category LIKE '%Cafe%' \n    OR c.category LIKE '%American%'\n    OR e.name LIKE '%Taco%'\n    OR e.name LIKE '%Burrito%'\n    OR e.name LIKE '%Bakery%'\n  )\nGROUP BY e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.slchd_establishment_key\nORDER BY e.avg_rating DESC, e.num_of_reviews DESC;"})

