Action: run_sql({'query': "SELECT e.name, r.rating, r.text \nFROM review r\nJOIN establishments e ON r.gmap_id = e.gmap_id\nWHERE (e.address LIKE '%84116%' OR e.address LIKE '%900 W%' OR e.address LIKE '%1000 N%' OR e.address LIKE '%700 N%')\n  AND (r.text LIKE '%breakfast%' OR r.text LIKE '%burrito%' OR r.text LIKE '%chorizo%' OR r.text LIKE '%huevos%' OR r.text LIKE '%chilaquiles%' OR r.text LIKE '%savory%')\nORDER BY e.avg_rating DESC, r.rating DESC\nLIMIT 25;"})

